import json, urllib.request, urllib.error, base64, io, zipfile

with open('/tmp/gh_token.txt', 'r') as f:
    github_token = f.read().strip()

REPO = "ibb142/ivx-holdings-platform"
MERGE_SHA = "cadd9f4b39ff77a40a61a60dfb38a13c5815bac2"

def github_api_raw(method, path, data=None):
    url = f"https://api.github.com/repos/{REPO}/{path}"
    headers = {
        'Authorization': f'token {github_token}',
        'Accept': 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28'
    }
    body = json.dumps(data).encode() if data else None
    req = urllib.request.Request(url, data=body, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            content = resp.read()
            return resp.status, content, dict(resp.headers)
    except urllib.error.HTTPError as e:
        body = e.read()
        return e.code, body, dict(e.headers)
    except Exception as e:
        return 0, str(e).encode(), {}

# Try to download logs as zip for each failed run
status, runs_data = github_api_raw('GET', f'actions/runs?head_sha={MERGE_SHA}&per_page=10')
runs = json.loads(runs_data.decode())

for run in runs.get('workflow_runs', []):
    run_id = run.get('id')
    name = run.get('name')
    conclusion = run.get('conclusion')
    if conclusion != 'failure':
        continue

    print(f"\n=== Downloading logs for {name} (run {run_id}) ===")
    s, log_data, headers = github_api_raw('GET', f'actions/runs/{run_id}/logs')
    print(f"  Status: {s}, Content-Length: {len(log_data)}, Content-Type: {headers.get('Content-Type', '?')}")

    if s == 200 and len(log_data) > 100:
        try:
            zf = zipfile.ZipFile(io.BytesIO(log_data))
            # Get all file names
            names = zf.namelist()
            print(f"  Log files: {len(names)}")

            # Read each log file and find errors
            for log_name in names:
                if log_name.endswith('.txt'):
                    content = zf.read(log_name).decode('utf-8', errors='replace')
                    lines = content.split('\n')
                    # Find error/failure lines
                    error_lines = []
                    for line in lines:
                        if any(kw in line.lower() for kw in ['error', 'fail', 'cannot find', 'not found', 'exit code', 'command not found', 'module not found', 'tsc error', 'bun error']):
                            # Skip false positives
                            if 'errorformat' in line.lower() or 'errorhandler' in line.lower():
                                continue
                            error_lines.append(line.strip()[:300])

                    if error_lines:
                        print(f"\n  --- {log_name} ({len(error_lines)} error lines) ---")
                        for el in error_lines[:15]:
                            print(f"    {el}")
        except Exception as e:
            print(f"  Failed to parse zip: {e}")
    else:
        print(f"  Could not download logs. Response: {log_data[:200]}")
